export async function claimEditCancel(page: Page, claimId: string): Promise<void> {
  await cancelOpenEditor(claimRow(page, claimId));
}

/** open | settle | void | approve | reject(reason) | void(reason): true when the status changed.
 *  A reject's reason is typed; a void's is chosen from the sheet's list. */
export async function claimAction(page: Page, claimId: string, action: string, reason?: string): Promise<boolean> {
  const c = claimRow(page, claimId);
  const was = await shown(c.getByTestId('claim-status'));
  if (reason !== undefined && action === 'void') {
    try {
      await c.getByTestId('claim-void-reason').selectOption({ label: reason }, { timeout: 2000 });
    } catch {
      return false;             // not offered: the screen refuses it by leaving it out
    }
  } else if (reason !== undefined && action === 'settle') {
    await c.getByTestId('claim-settle-date').fill(reason);
  } else if (reason !== undefined) await c.getByTestId('claim-reject-reason').fill(reason);
  await c.getByTestId(`claim-${action}`).click();
  return until(page, async () => await shown(c.getByTestId('claim-status')) !== was,
    c.getByTestId('claim-error'), `claim ${action}`);
}

/** Re-settle a settled claim: true once its status log gained a line. */
export async function resettle(page: Page, claimId: string): Promise<boolean> {
  const c = claimRow(page, claimId);
  const lines = c.getByTestId('claim-log-line');
  const was = await lines.count();
  await c.getByTestId('claim-resettle').click();
  return until(page, async () => (await lines.count()) > was, c.getByTestId('claim-error'), 're-settle');
}

/** Defer an open claim until a date: true once the row shows the date. */
export async function defer(page: Page, claimId: string, until_: string): Promise<boolean> {
  const c = claimRow(page, claimId);
  const done = async () => (await shown(c.getByTestId('claim-deferred-until'))) === until_;
  const already = await done();
  await c.getByTestId('claim-defer-date').fill(until_);
  await c.getByTestId('claim-defer').click();
  return until(page, done, c.getByTestId('claim-error'), 'defer', already);
}

/** Raise the claim's proofs count by one (of a kind, when the claim offers kinds): true once the count moved. */
export async function addProof(page: Page, claimId: string, kind?: string): Promise<boolean> {
  const c = claimRow(page, claimId);
  const was = await shown(c.getByTestId('claim-proofs'));
  if (kind !== undefined) {
    try {
      await c.getByTestId('claim-proof-kind').selectOption(kind, { timeout: 2000 });
    } catch {
      return false;
    }
  }
  await c.getByTestId('claim-proof').click();
  return until(page, async () => (await shown(c.getByTestId('claim-proofs'))) !== was,
    c.getByTestId('claim-error'), 'add proof');
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.period.PeriodClosedException;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.setting.Permissions;
import net.officefloor.hq.app.setting.RoleRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Voids a claim; an opened claim keeps its number (still never reused). Refused for a role the
 *  permission matrix does not let void. */
public class VoidClaim {
    public void move(@RequestParam(name = "by", required = false) String by, @Val Claim claim,
            PeriodRepository periods, RoleRepository roles, SettingRepository settings)
            throws ClaimStatusException, PeriodClosedException {
        if (!Permissions.allows(claim.getSheetId(), by, Permissions.VOID, roles, settings)) {
            throw new ClaimStatusException("Your role may not void a claim");
        }
        periods.requireOpen(claim.getSheetId(), claim.getDate());
        claim.setStatus(ClaimStatus.valueOf(claim.getStatus()).moveTo(ClaimStatus.VOID).name());
    }
}
package net.officefloor.hq.app.claim;

/** A claim's status. It starts DRAFT; DRAFT opens to OPEN, OPEN settles to SETTLED (or, settled by a
 *  clerk above the clerk limit, to PENDING), PENDING is approved to SETTLED or rejected back to OPEN,
 *  and DRAFT, OPEN or PENDING voids to VOID. SETTLED and VOID are final. */
public enum ClaimStatus {
    DRAFT, OPEN, PENDING, SETTLED, VOID;

    /** The status after moving to {@code to}; refused when this status does not allow it. */
    public ClaimStatus moveTo(ClaimStatus to) throws ClaimStatusException {
        boolean allowed = switch (to) {
            case OPEN -> this == DRAFT || this == PENDING;
            case PENDING -> this == OPEN;
            case SETTLED -> this == OPEN || this == PENDING;
            case VOID -> this == DRAFT || this == OPEN || this == PENDING;
            case DRAFT -> false;
        };
        if (!allowed) {
            throw new ClaimStatusException("A " + this + " claim cannot become " + to);
        }
        return to;
    }

    /** Whether a claim with this status is open: OPEN, or PENDING (awaiting a steward's approval). */
    public static boolean isOpen(String status) {
        return OPEN.name().equals(status) || PENDING.name().equals(status);
    }

    /** The audit event recorded when a claim moves to this status. */
    public String event() {
        return switch (this) {
            case OPEN -> "CLAIM_OPENED";
            case PENDING -> "CLAIM_PENDING";
            case SETTLED -> "CLAIM_SETTLED";
            case VOID -> "CLAIM_VOIDED";
            case DRAFT -> "CLAIM_DRAFTED";
        };
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Last write step: only a status change that went through is recorded. */
public class RecordClaimStatus {
    public void record(@RequestParam(name = "by", required = false) String by,
            @Val Claim claim, PersonRepository people, Audit audit) {
        audit.record(line(ClaimStatus.valueOf(claim.getStatus()).event(), by, claim, people)
                + (ClaimStatus.SETTLED.name().equals(claim.getStatus()) ? due(claim) : ""));
    }

    /** A claim line: the event, the sheet, the user, then the claim's person, amount, date and number. */
    static String line(String event, String by, Claim claim, PersonRepository people) {
        Person person = people.find(claim.getSheetId(), claim.getPersonId());
        return event + " sheet=" + claim.getSheetId()
                + " by=" + (by == null ? "" : by)
                + " person=" + (person == null ? "" : person.getName())
                + " amount=" + claim.getAmount() + " date=" + claim.getDate()
                + claim.getAuditNumber();
    }

    /** The fixed due suffix of a settled claim. */
    static String due(Claim claim) {
        return " due=" + (claim.getSettledDue() == null ? "n/a" : claim.getSettledDue());
    }
}
